import {lessonTables} from './tables';
import {earlyStory,storyBridges} from './story';
export type Table = {caption:string; headers:string[]; rows:string[][]; note?:string};
export type Question = {prompt:string;options:string[];answer:number;explanation:string};
type Quiz = [string,string,string,string,string];
export type Lesson = {id:string;slug:string;title:string;desc:string;unit:number;rule:string;example:string;translation:string;reading:string;english:string;words:[string,string][];questions:Question[];speak:string;tables:Table[]};
export const units = [
{title:'Alphabet & pronunciation',level:'Foundations',description:'Letters, mouth position, sound patterns, and greetings.'},
{title:'First sentences & nouns',level:'Beginner',description:'Subjects, essential verbs, gender, articles, and plurals.'},
{title:'Descriptions & present tense',level:'Beginner',description:'Definite nouns, adjective agreement, and verb families.'},
{title:'Everyday sentence patterns',level:'Beginner',description:'Questions, negatives, quantities, places, and routines.'},
{title:'Possession & objects',level:'Developing',description:'Determiners, comparisons, object pronouns, and cases.'},
{title:'Time & verb moods',level:'Intermediate',description:'Past narratives, future plans, and the subjunctive.'},
{title:'Complex sentences',level:'Intermediate',description:'Commands, relative clauses, pronoun order, and conditionals.'},
{title:'Extended grammar',level:'Upper intermediate',description:'Indefinites, passive constructions, linking ideas, and reported speech.'},
{title:'Advanced usage & literature',level:'Advanced topics',description:'Nuance, literary forms, register, and close reading.'}
];
const raw:Omit<Lesson,'id'|'slug'|'unit'|'tables'>[]=[];
function L(title:string,desc:string,rule:string,example:string,translation:string,reading:string,english:string,words:[string,string][],qs:Quiz[],speak:string){
const questions=qs.map(([prompt,correct,a,b,explanation],i)=>{const offset=(raw.length+i)%3;const options=[correct,a,b];return {prompt,options:[...options.slice(offset),...options.slice(0,offset)],answer:(3-offset)%3,explanation}});
raw.push({title,desc,rule,example,translation,reading,english,words,questions,speak});}
// Chapter 1
L('The Romanian alphabet','Recognize all 31 letters and distinguish letter names from sounds.',
'Romanian uses the Latin alphabet with five additional letters: ă, â, î, ș, and ț. Diacritics change the sound, so treat these as separate letters rather than optional decoration. The alphabet table gives the usual sound and a real word; a letter name is not the sound you use inside a word. Read the examples in syllables first, then blend them.\n\nMost letters have a stable sound, but c and g depend on the next letter. K, q, w, and y occur mainly in loanwords and names. Do not apply English vowel names to Romanian words: a is an open “ah,” not the diphthong in “name.” The next four lessons isolate these sound patterns before introducing grammar.',
'Ana are o carte.','Ana has a book.','Ana. Maria. O carte. Un parc. România.','Ana. Maria. A book. A park. Romania.',[['carte','book'],['parc','park'],['România','Romania']],
[['Which spelling preserves the Romanian letter meaning “sh”?','ș','s','ț','Ș is a separate letter representing /ʃ/. Removing its comma changes the sound.'],['Which group contains the five additional Romanian letters?','ă, â, î, ș, ț','a, e, i, o, u','c, g, k, q, y','Ă, â, î, ș, and ț are distinct letters in the 31-letter alphabet.'],['Which country appears in the reading?','România','Italia','Germania','The final word is România: Romania.']],
'Read Ana, Maria, carte, parc, România. Spell your own name, then identify any sounds it contains that Romanian writes differently.');
L('Vowels: a, e, i, o, u','Place the five basic vowels and avoid English-style glides.',
'Keep Romanian vowels relatively steady. For a /a/, open your mouth and keep your tongue low: Ana, apă, casa. For e /e/, place your tongue toward the front at mid height: elev, mere, pere. For i /i/, lift the front of your tongue: inel, inimă, mic. English “see” is an approximation, but avoid a trailing glide.\n\nFor o /o/, round your lips with the tongue at mid-back height: om, opt, pom. For u /u/, round the lips more tightly and raise the back of your tongue: unu, lună, bun. Compare pom and pumn without adding an English “oh” or “oo-w” movement. Some initial e words are pronounced with /j/, especially forms of a fi and pronouns: eu, el, este. Treat those as learned word patterns.',
'Ana are mere.','Ana has apples.','Ana are mere. Maria are pere. Un om are un inel.','Ana has apples. Maria has pears. A man has a ring.',[['mere','apples'],['pere','pears'],['inel','ring']],
[['Which vowel uses rounded lips and a high back tongue position?','u','a','e','U /u/ is high and back with rounded lips. A is open; e is front and mid.'],['Which word starts with a vowel commonly pronounced with a /j/ onset?','este','mere','pom','Este is conventionally pronounced with an initial /j/ in standard speech.'],['What does Maria have?','Pears','Apples','A ring','Maria are pere: Maria has pears.']],
'Say a–e–i–o–u slowly, keeping each vowel steady. Read Ana are mere, then Maria are pere.');
L('Ă, â, and î','Learn the central vowels with mouth-position notes and contrasts.',
'Ă is /ə/, a relaxed central vowel. Let your tongue rest near the middle of the mouth and keep the lips unrounded. The final vowel of English “sofa” is a useful approximation: fată, masă, apă, bună. Do not replace it with open /a/: fata and fată have different endings and different grammatical roles. Compare masă /ˈma.sə/ with masa /ˈma.sa/.\n\nÂ and î both represent /ɨ/. Start from a steady /i/, then move the tongue body backward toward the center without rounding the lips. There is no exact equivalent in most English accents. Practice în, înger, mână, pâine, român. Î usually appears at the beginning or end of a word; â usually occurs inside. Compounds such as neînțeles preserve an internal î. These are spelling patterns, not two different vowel sounds.',
'Pe masă este pâine.','There is bread on the table.','Pe masă este apă. Este și pâine. Ana are o mână pe masă.','There is water on the table. There is bread too. Ana has one hand on the table.',[['masă','table'],['pâine','bread'],['mână','hand']],
[['How do â and î differ in pronunciation?','They represent the same vowel /ɨ/.','Â is rounded; î is unrounded.','Â is always stressed; î never is.','The difference is mainly spelling position. Both letters represent /ɨ/.'],['Which word ends in the relaxed vowel /ə/?','masă','masa','mic','The final ă in masă is /ə/. The final a in masa is /a/.'],['What two things are on the table?','Water and bread','Apples and pears','Coffee and tea','The passage says apă and pâine are on the table.']],
'Alternate masă–masa, fată–fata, then în–mână–pâine. Record both vowels and check that your lips stay unrounded.');
L('Consonants and spelling groups','Read ș, ț, c, g, ch, gh, and Romanian r.',
'Ș /ʃ/ is the sound in English “ship”: șase, școală, oraș. Ț /t͡s/ is one connected sound, like the ending of “cats”: țară, puțin, mulțumesc. Romanian r is typically tapped or trilled, using the tongue tip near the ridge behind the upper teeth: mare, rece, tren. It is not the usual English r. H is audible in words such as hotel.\n\nBefore e or i, c is /t͡ʃ/ as in “church”: ce, cine, cinci; g is /d͡ʒ/ as in “jam”: ger, girafă. Elsewhere c is /k/ (carte, copil) and g is /g/ (gară, gură). Insert h to keep the hard sound before e/i: cheie, chip, gheață, ghid. The h in ch/gh is part of the spelling group; do not pronounce it separately.',
'Cinci chei sunt pe masă.','Five keys are on the table.','Cinci chei sunt pe masă. Un ghid este în gară. În oraș este o școală.','Five keys are on the table. A guide is at the station. There is a school in the city.',[['cheie','key'],['gară','station'],['școală','school']],
[['Which word begins with /k/, not /t͡ʃ/?','cheie','cine','cinci','Ch before e/i keeps /k/. C without h before e/i becomes /t͡ʃ/.'],['Which word begins with the connected sound /t͡s/?','țară','șase','gară','Ț is /t͡s/; ș is /ʃ/; g before a is /g/.'],['Where is the guide?','At the station','At school','At the table','Un ghid este în gară: a guide is at the station.']],
'Compare ce–cheie, ge–gheață, șase–țară. Read the full passage without adding a separate h sound in chei or ghid.');
L('Syllables, stress, and final i','Notice word stress, vowel groups, and consonant softening.',
'Romanian stress is not normally written and cannot always be predicted. Learn it with each new word: CÁR-te, ca-FEÁ, fe-REÁS-tră. The capital letters here are teaching annotations, not normal Romanian spelling. Pronounce unstressed vowels clearly rather than reducing every unstressed vowel to an English schwa. A vowel group can share a syllable, as in seară (sea-ră), or form separate syllables, as in poet (po-et).\n\nA final unstressed i often marks a softened preceding consonant without becoming a full syllable: pom → pomi, lup → lupi. It is not always silent and not always a full “ee.” Compare copii (children) and copiii (the children), whose written endings reflect different morphology. For now, recognize the spelling and listen to the full word rather than counting written i letters as syllables.',
'Copiii sunt în parc.','The children are in the park.','Este seară. Copiii sunt în parc. Ana are o carte și o cafea.','It is evening. The children are in the park. Ana has a book and a coffee.',[['seară','evening'],['copii','children'],['fereastră','window']],
[['Where is the stress in cafea?','On the last syllable: ca-FEÁ','On the first syllable: CÁ-fea','Both syllables are always equally stressed','Cafea is stressed on its final syllable. Stress marks here are teaching aids.'],['What does a final unstressed i often do?','Softens the preceding consonant','Makes every word one syllable longer','Changes c to /k/ in every word','Final i often signals consonant palatalization; pronunciation depends on the word.'],['When does the scene take place?','In the evening','In the morning','At noon','Este seară means it is evening.']],
'Read CAR-te, ca-FEA, fe-REAS-tră; then say them without pausing. Compare pom–pomi and read Copiii sunt în parc.');
L('Greetings and introductions','Choose an appropriate greeting and introduce yourself.',
'Use Bună or Salut with friends. Bună dimineața is good morning, Bună ziua is a polite daytime greeting, and Bună seara is good evening. Noapte bună is a farewell before sleeping, not the usual greeting when arriving in the evening. Say Mulțumesc for thank you and Cu plăcere for you are welcome.\n\nMă numesc Ana means my name is Ana. Cum te cheamă? asks a name informally; Cum vă numiți? is a polite alternative. Îmi pare bine means nice to meet you. Learn these as complete conversational expressions first; reflexive and object pronouns will receive separate lessons later. A short natural reply can omit repeated information: Și mie! = me too.',
'Bună! Mă numesc Ana.','Hello! My name is Ana.','— Bună ziua! Mă numesc Ana.\n— Bună ziua, Ana! Eu sunt Radu.\n— Îmi pare bine!\n— Și mie!','— Hello! My name is Ana.\n— Hello, Ana! I am Radu.\n— Nice to meet you!\n— Me too!',[['bună','hello'],['mulțumesc','thank you'],['nume','name']],
[['Which greeting is suitable when arriving in the evening?','Bună seara!','Noapte bună!','La revedere!','Bună seara greets someone in the evening. Noapte bună is usually a bedtime farewell.'],['Which question is a polite way to ask a name?','Cum vă numiți?','Cum te cheamă?','Unde este gara?','Vă in Cum vă numiți marks the polite/plural form.'],['What is the second speaker’s name?','Radu','Ana','Maria','The second speaker says Eu sunt Radu.']],
'Greet a new classmate, introduce yourself, ask their name, and say nice to meet you. Repeat the conversation in a polite register.');
// Chapter 2
L('Subject pronouns','Choose eu, tu, el, ea, noi, voi, ei, and ele.',
'A subject tells us who performs an action. Romanian subject pronouns are eu, tu, el/ea, noi, voi, and ei/ele. El and ei are masculine; ea and ele are feminine. A group containing mixed genders normally uses ei. Unlike English, Romanian usually omits the subject pronoun when the verb form makes it clear: Sunt Ana is already a complete sentence.\n\nUse an explicit pronoun for contrast or emphasis: Eu sunt Ana; ea este Maria. Dumneavoastră is polite you, used with plural verb forms even when addressing one person. Tu is informal singular; voi is familiar plural. Keep the register consistent within a conversation. The next lesson supplies the full forms of a fi, to be.',
'Eu sunt Ana; ea este Maria.','I am Ana; she is Maria.','Eu sunt Ana. El este Radu. Ea este Maria. Noi suntem aici. Voi sunteți în parc.','I am Ana. He is Radu. She is Maria. We are here. You are in the park.',[['aici','here'],['noi','we'],['voi','you (plural)']],
[['Which pronoun refers to a group of women?','ele','ei','ea','Ele is feminine plural. Ea is feminine singular.'],['Which pronoun takes plural verb forms as polite “you”?','dumneavoastră','tu','eu','Dumneavoastră takes the second-person plural verb form.'],['Which people are “here” in the reading?','We','You','Only Maria','Noi suntem aici means we are here.']],
'Introduce three imaginary classmates using eu, el, and ea. Then refer to the whole group with noi.');
L('A fi: to be','Conjugate the present tense and build simple descriptions.',
'The present tense of a fi is irregular: sunt, ești, este, suntem, sunteți, sunt. Match the verb to the subject, even when the pronoun is omitted. Eu sunt and ei sunt share a form, so context or an explicit pronoun can resolve ambiguity. Este also has the common short form e.\n\nUse a fi with identity, origin, location, or a description: Sunt student. Sunt din România. Sunt în parc. Sunt obosit. Romanian usually does not need an indefinite article before a profession used this way: Ea este profesoară. Adjectives may change with gender: obosit for a male speaker, obosită for a female speaker.',
'Noi suntem în București.','We are in Bucharest.','Ana este studentă. Radu este profesor. Ei sunt în București. Maria este din Brașov. Noi suntem în parc.','Ana is a student. Radu is a teacher. They are in Bucharest. Maria is from Brașov. We are in the park.',[['studentă','female student'],['profesor','teacher'],['obosit','tired (masculine)']],
[['Complete: Tu ___ student.','ești','este','sunteți','Tu requires ești; este is third person and sunteți is plural/polite you.'],['Which sentence means “She is a teacher”?','Ea este profesoară.','Ea sunt profesoară.','Ea suntem profesoară.','Ea takes este. A profession after a fi normally does not need an indefinite article.'],['Where is Maria from?','Brașov','București','The park','Maria este din Brașov states her origin.']],
'Say who you are, where you are from, and where you are now. Then describe a friend using este.');
L('A avea: to have','Express possession and age with am, ai, are, avem, aveți, au.',
'A avea has the present forms am, ai, are, avem, aveți, au. It expresses possession: Am o carte. In Romanian, age also uses a avea rather than a fi: Am douăzeci de ani. The full number system comes later; learn the age construction now.\n\nA noun after a avea is the thing possessed. Put a useful phrase around the verb: Ana are o carte; noi avem o masă; voi aveți apă. Romanian has no obligatory equivalent of English “some” before every plural or mass noun: Am mere and Am apă are natural. Negation will be taught separately; the basic pattern is nu + verb.',
'Noi avem apă.','We have water.','Ana are o carte. Radu are un caiet. Noi avem apă și pâine. Voi aveți mere. Ei au o masă în parc.','Ana has a book. Radu has a notebook. We have water and bread. You have apples. They have a table in the park.',[['caiet','notebook'],['apă','water'],['ani','years']],
[['Complete: Ei ___ un caiet.','au','are','avem','Ei is third-person plural, so the form is au.'],['Which verb does Romanian normally use for age?','a avea','a fi','a merge','Age is expressed as having years: Am douăzeci de ani.'],['What does Radu have?','A notebook','A book','A table','Radu are un caiet means Radu has a notebook.']],
'Describe three things you have. Ask a partner what they have using Ai…? and reply with Am….');
L('Noun gender','Identify masculine, feminine, and neuter nouns.',
'Romanian nouns belong to three genders. Learn a noun with an article: un băiat (masculine), o fată (feminine), un scaun (neuter). Neuter is visible through its pattern: masculine agreement in the singular and feminine agreement in the plural. A noun’s meaning alone does not reliably reveal its grammatical gender.\n\nEndings are clues, not guarantees. Many nouns ending in ă are feminine, while consonant endings often indicate masculine or neuter. Carte is feminine despite ending in e; nume is neuter. Learn a useful testing pair: un–doi for masculine, o–două for feminine, un–două for neuter. The table uses the correct forms un–doi, o–două, and un–două.',
'Am un scaun și o masă.','I have a chair and a table.','În cameră este o masă. Pe masă este o carte. Ana are un scaun. Radu are un caiet. Camera este mică.','There is a table in the room. On the table is a book. Ana has a chair. Radu has a notebook. The room is small.',[['scaun','chair'],['cameră','room'],['masă','table']],
[['Which testing pair identifies a neuter noun?','un — două','un — doi','o — două','Neuter nouns take masculine singular and feminine plural agreement: un scaun, două scaune.'],['What is the gender of carte?','Feminine','Masculine','Always neuter','We say o carte and două cărți. Endings give clues but do not settle every noun.'],['Where is the book?','On the table','On the chair','In the park','Pe masă este o carte places the book on the table.']],
'Name three things in your room with un or o. For each, check its gender in the table.');
L('Indefinite articles','Use un, o, and niște for nonspecific things.',
'Use un with masculine and neuter singular nouns, and o with feminine singular nouns. Un caiet means a notebook; o carte means a book. Choose the article from the noun’s gender, not from the gender of the person who owns it. A woman can have un caiet; a man can have o carte.\n\nNiște can introduce an indefinite plural: niște cărți, some books. It can also mean some with a mass noun: niște apă. Romanian frequently omits it when a general amount is enough: Am apă. Do not confuse o as an article with o as an object pronoun; later lessons explain pronouns in context.',
'Vreau o cafea și un ceai.','I want a coffee and a tea.','Ana este într-o cafenea. Are o carte și un caiet. Pe masă sunt niște mere. Radu are un ceai. Ana are o cafea și apă.','Ana is in a café. She has a book and a notebook. There are some apples on the table. Radu has a tea. Ana has a coffee and water.',[['cafea','coffee'],['ceai','tea'],['mere','apples']],
[['Choose the article: ___ carte.','o','un','doi','Carte is feminine singular, so it takes o.'],['Which phrase means “some books”?','niște cărți','un cărți','o cărți','Niște is an indefinite plural article; un and o are singular.'],['What does Radu have to drink?','Tea','Coffee','Only water','Radu are un ceai states that he has a tea.']],
'Order a coffee, a tea, and some water. Repeat the order using un, o, and niște correctly.');
L('Plural nouns','Learn common plural endings and stem changes.',
'Romanian plurals use several patterns. Masculine nouns often take i: student → studenți, pom → pomi. Feminine nouns commonly take e or i: fată → fete, carte → cărți. Neuter nouns often take e or uri: scaun → scaune, tren → trenuri. There is no single ending that works for every noun.\n\nStem changes are common: fată → fete changes ă to e; carte → cărți changes both the vowel and final consonant spelling. Learn each noun as a pair, including its gender. When counting, use doi for masculine plurals but două for feminine and neuter plurals: doi studenți, două cărți, două scaune.',
'Două cărți sunt pe masă.','Two books are on the table.','În cameră sunt două mese și patru scaune. Pe o masă sunt două cărți și trei caiete. Doi studenți sunt aici. Ei au mere și apă.','There are two tables and four chairs in the room. On one table are two books and three notebooks. Two students are here. They have apples and water.',[['cărți','books'],['scaune','chairs'],['tren','train']],
[['What is the plural of carte?','cărți','carteuri','cartă','Carte changes to cărți. Learn the stem alternation with the plural.'],['Which phrase correctly counts neuter chairs?','două scaune','doi scaune','două scauni','Scaun is neuter and takes feminine counting agreement in the plural.'],['How many notebooks are on the table?','Three','Two','Four','Trei caiete means three notebooks.']],
'Inventory a room using plural nouns. Include doi studenți, două cărți, and două scaune.');
// Chapter 3
L('Definite articles','Attach “the” to singular and plural nouns.',
'Romanian usually attaches the definite article to the end of the noun. Compare un băiat → băiatul, o fată → fata, o carte → cartea, un scaun → scaunul. Final ă commonly becomes a; an e-ending feminine noun commonly adds a. The article identifies a particular person or thing already known in the conversation.\n\nPlural definite forms also vary by gender and ending: băieți → băieții, fete → fetele, scaune → scaunele. Watch written final i: copii means children, while copiii means the children. Many simple prepositional expressions omit the definite article, such as la școală; do not mechanically translate every English “the.”',
'Cartea este pe masă.','The book is on the table.','Ana are o carte. Cartea este pe masă. Radu are un caiet. Caietul este în cameră. Studenții sunt în parc, iar fetele sunt la școală.','Ana has a book. The book is on the table. Radu has a notebook. The notebook is in the room. The students are in the park, while the girls are at school.',[['băiat','boy'],['fată','girl'],['școală','school']],
[['Choose the definite form of carte.','cartea','o carte','cărți','Cartea attaches the feminine definite article to carte.'],['Which spelling means “the children”?','copiii','copii','copil','Copii is indefinite plural; copiii is definite plural.'],['Where is the notebook?','In the room','At school','In the park','Caietul este în cameră places it in the room.']],
'Introduce a book, a chair, and a notebook with un/o, then refer to each again with its definite form.');
L('Adjective agreement','Describe nouns in all four gender-number forms.',
'An adjective agrees with the noun it describes, not with the speaker. Many adjectives have four forms: bun, bună, buni, bune. Thus un băiat bun, o fată bună, băieți buni, fete bune. A neuter noun uses the masculine singular and feminine plural forms: un scaun bun, scaune bune.\n\nAdjectives usually follow the noun: o carte interesantă. They also agree after a fi: Cartea este interesantă; cărțile sunt interesante. Not every adjective has four different forms: mare has the plural mari for both genders. Preposed adjectives are possible and can change emphasis or article placement, but the noun-first pattern is the safest starting point.',
'Cărțile sunt interesante.','The books are interesting.','Camera este mică, dar ferestrele sunt mari. Pe masa nouă sunt două cărți interesante. Un student obosit are un caiet nou. Studentele sunt obosite, dar cărțile sunt bune.','The room is small, but the windows are large. On the new table are two interesting books. A tired student has a new notebook. The female students are tired, but the books are good.',[['nou','new'],['mare','large'],['interesant','interesting']],
[['Complete: două scaune ___.','noi','nou','nouă','The plural of nou is noi for both masculine and feminine; neuter scaune uses plural agreement.'],['Complete: Fetele sunt ___.','obosite','obosit','obosiți','Fetele is feminine plural, so obosit becomes obosite.'],['Are the windows large or small?','Large','Small','The text does not say.','Ferestrele sunt mari means the windows are large.']],
'Describe a room with three noun–adjective pairs. Change each pair from singular to plural.');
L('Present tense: -a verbs','Conjugate a lucra and recognize the -ez pattern.',
'Romanian groups infinitives by endings, but a group does not predict every present form. A lucra uses the -ez pattern: lucrez, lucrezi, lucrează, lucrăm, lucrați, lucrează. First find the subject, then choose the matching form. Notice the stem expansion in singular persons and third-person plural; noi and voi use lucr- without ez.\n\nSome -a verbs do not use ez: a cânta gives cânt, cânți, cântă, cântăm, cântați, cântă. Learn the infinitive alongside eu, tu, and el/ea forms to spot the pattern. The present can describe a current action or a habit: Lucrez acum and Lucrez în fiecare zi use the same tense.',
'Ana lucrează acasă.','Ana works at home.','Ana lucrează acasă. Dimineața, ea lucrează în camera mică. Radu cântă în parc. Noi lucrăm la școală, iar voi lucrați în oraș. Seara, studenții cântă și citesc.','Ana works at home. In the morning, she works in the small room. Radu sings in the park. We work at school, while you work in the city. In the evening, the students sing and read.',[['acasă','at home'],['a lucra','to work'],['a cânta','to sing']],
[['Complete: Noi ___ acasă.','lucrăm','lucrez','lucrează','Noi requires lucrăm, without the ez expansion.'],['Which statement about -a verbs is correct?','Some use -ez and others do not.','All use exactly the same stem pattern.','They have no plural forms.','Compare lucrez with cânt: both infinitives end in a but their present patterns differ.'],['Where does Radu sing?','In the park','At home','At school','Radu cântă în parc identifies the location.']],
'Describe where you work or study. Conjugate a lucra with eu, noi, and ei, then contrast cânt and cântăm.');
L('Present tense: -e and -ea verbs','Build present forms of a merge, a face, and a vedea.',
'A merge (to go) has merg, mergi, merge, mergem, mergeți, merg. A face (to do/make) has fac, faci, face, facem, faceți, fac. The endings are similar, but spelling changes reflect the sound rules: c/g before e/i have their soft values. Do not pronounce faci with a hard k.\n\nA vedea belongs to the -ea group and has văd, vezi, vede, vedem, vedeți, văd. Its stem alternations must be learned. Use these verbs with a destination or object: merg la școală, fac o cafea, văd un parc. A merge is normally intransitive: you go to a place, rather than directly “go a place.”',
'Noi mergem la școală.','We go to school.','Dimineața merg la școală. Pe drum văd un parc și o cafenea. Ana face o cafea acasă, apoi merge în oraș. Noi vedem studenții în parc. Ei fac o pauză și citesc.','In the morning I go to school. On the way I see a park and a café. Ana makes a coffee at home, then goes into town. We see the students in the park. They take a break and read.',[['a merge','to go'],['a face','to do / make'],['a vedea','to see']],
[['Complete: Voi ___ la școală.','mergeți','mergem','merg','Voi takes mergeți. Noi takes mergem.'],['Complete: Eu ___ un parc.','văd','vede','vedem','The first-person singular of a vedea is văd.'],['What does Ana do before going into town?','Makes a coffee','Goes to school','Sings in the park','Ana face o cafea acasă, apoi merge în oraș.']],
'Describe a short route using merg and văd. Explain what you do at the destination using fac.');
L('Present tense: -i and -î verbs','Compare -esc, -ăsc, and unexpanded present patterns.',
'A citi uses -esc in the present: citesc, citești, citește, citim, citiți, citesc. Notice the change esc → ești → ește and its absence in noi/voi. A vorbi follows the same broad pattern: vorbesc, vorbești, vorbește, vorbim, vorbiți, vorbesc. Learn the stressed syllable with the forms.\n\nNot all -i verbs take esc: a dormi gives dorm, dormi, doarme, dormim, dormiți, dorm. A hotărî uses -ăsc: hotărăsc, hotărăști, hotărăște, hotărâm, hotărâți, hotărăsc. The infinitive ending is a starting clue; the full paradigm and stem changes still matter.',
'Noi citim în fiecare seară.','We read every evening.','Seara, Ana citește o carte în română. Radu vorbește cu un prieten, iar copiii dorm. Noi citim acasă. Voi vorbiți la școală. În cameră este liniște și fereastra este deschisă.','In the evening, Ana reads a book in Romanian. Radu talks with a friend, while the children sleep. We read at home. You speak at school. It is quiet in the room and the window is open.',[['a citi','to read'],['a vorbi','to speak'],['a dormi','to sleep']],
[['Complete: Tu ___ o carte.','citești','citesc','citim','Tu takes citești; citesc is eu or ei/ele.'],['Which verb does not use -esc in the present?','a dormi','a citi','a vorbi','A dormi has dorm, dormi, doarme rather than an -esc pattern.'],['What are the children doing?','Sleeping','Reading','Talking','Copiii dorm means the children are sleeping.']],
'Tell someone what you read and which languages you speak. Change the subject to noi and repeat.');
L('Frequent irregular verbs','Use a vrea, a putea, a ști, and a lua.',
'Frequent verbs often have irregular stems. A vrea: vreau, vrei, vrea, vrem, vreți, vor. A putea: pot, poți, poate, putem, puteți, pot. A ști: știu, știi, știe, știm, știți, știu. Write știi with two i letters in the second-person singular.\n\nA lua (to take) gives iau, iei, ia, luăm, luați, iau. Use vrea with a noun for now: Vreau apă. A putea can precede a bare infinitive: Pot citi. With vrea, a second verb usually uses să: Vreau să citesc; the subjunctive receives a dedicated lesson later. Do not build every modal construction by copying English word order.',
'Pot citi în română.','I can read in Romanian.','Ana vrea o carte nouă. Radu poate citi în română, dar nu știe toate cuvintele. Noi luăm două caiete și mergem la bibliotecă. Acolo, studenții vor o masă lângă fereastră.','Ana wants a new book. Radu can read in Romanian, but does not know all the words. We take two notebooks and go to the library. There, the students want a table by the window.',[['a putea','to be able to'],['a ști','to know'],['bibliotecă','library']],
[['Complete: Tu ___ răspunsul.','știi','știe','știu','Tu requires știi, with two written i letters.'],['Complete: Noi ___ două caiete.','luăm','iau','iei','The first-person plural of a lua is luăm.'],['Does Radu know every word?','No','Yes','The reading never mentions words.','Nu știe toate cuvintele means he does not know all the words.']],
'Say what you want, what you can do, and what you know. Include one form of a lua.');
// Chapter 4
L('Negation and basic word order','Build statements and place nu before the verb.',
'The neutral sentence pattern is subject–verb–object: Ana citește o carte. Romanian word order is flexible for emphasis, but this is a reliable starting point. If you omit the subject, begin with the verb: Citesc o carte. Adjectives usually remain with their nouns rather than floating to the end of the sentence.\n\nNegate a finite verb by placing nu before it: Ana nu citește. With a simple modal construction, place nu before the modal: Nu pot citi. In ordinary neutral speech, nu is not placed after the conjugated verb. With clitic pronouns, nu comes before the clitic as well: Nu o văd. That more advanced pattern will return in the object-pronoun lessons.',
'Ana nu citește acum.','Ana is not reading now.','Ana are o carte, dar nu citește acum. Ea lucrează acasă. Radu nu merge în oraș, pentru că este obosit. Noi nu avem cafea, dar avem ceai. Seara, studenții citesc în bibliotecă.','Ana has a book, but she is not reading now. She is working at home. Radu is not going into town because he is tired. We do not have coffee, but we have tea. In the evening, the students read in the library.',[['acum','now'],['dar','but'],['obosită','tired (feminine)']],
[['Negate “Pot citi.”','Nu pot citi.','Pot nu citi.','Pot citi nu.','Place nu before the conjugated modal pot in the neutral negative construction.'],['Which is the neutral statement order?','Ana citește o carte.','Ana o carte citește is the only possible order.','Citește Ana carte o.','Subject–verb–object is a useful neutral pattern, though Romanian allows motivated variations.'],['Why is Radu staying out of town?','He is tired.','He has no books.','He wants coffee.','Pentru că este obosit gives the reason.']],
'Say three things you do today and three things you do not do. Keep nu immediately before the finite verb.');
L('Asking questions','Use intonation and question words without English do-support.',
'A yes/no question can keep statement word order and change the intonation: Ai o carte? Romanian does not insert English “do” or “does.” A subject pronoun can remain omitted. Intonation rises naturally with many yes/no questions, but avoid treating every question as the same melody.\n\nUse cine for who, ce for what, unde for where, când for when, cum for how, and de ce for why. The question phrase usually comes early: Unde lucrezi? Ce citești? De ce nu vii? Care asks which or identifies someone/something among alternatives. Later lessons explain case forms such as cui and pe cine.',
'Unde lucrezi?','Where do you work?','— Unde lucrezi, Ana?\n— Lucrez acasă. Tu unde mergi?\n— Merg la bibliotecă.\n— Ce citești acolo?\n— Citesc o carte despre România. Vii și tu?\n— Da, dar nu acum.','— Where do you work, Ana?\n— I work at home. Where are you going?\n— I am going to the library.\n— What are you reading there?\n— A book about Romania. Are you coming too?\n— Yes, but not now.',[['unde','where'],['când','when'],['de ce','why']],
[['Ask “What are you reading?”','Ce citești?','Unde citești?','Când citești?','Ce asks what; unde asks where; când asks when.'],['What extra auxiliary does Romanian need for “Do you have a book?”','None: Ai o carte?','A form of “do”','A form of a fi before ai','Romanian does not use English-style do-support.'],['What is the book about?','Romania','Coffee','A school','Despre România means about Romania.']],
'Interview someone with ce, unde, când, cum, and de ce. Answer each question in a complete sentence.');
L('Numbers and quantities','Count, agree with gender, and use de with larger quantities.',
'Learn zero through ten first, then the teen and tens patterns. Un/doi count masculine nouns; o/două count feminine nouns. Neuter uses un in the singular but două in the plural. Thus un student, doi studenți; o carte, două cărți; un scaun, două scaune.\n\nNumbers from twenty generally link to a counted noun with de: douăzeci de cărți. For everyday whole-number quantities of twenty and above, retain de in examples such as douăzeci și două de cărți. Time, decimals, and specialized measures have additional conventions. Câtă apă? asks about a feminine mass noun; câte cărți? asks about countable feminine plural nouns.',
'Am douăzeci de cărți.','I have twenty books.','La bibliotecă sunt douăzeci de studenți. Ana are două cărți, iar Radu are trei caiete. Pe masa mare sunt douăsprezece mere și patru pahare cu apă. Un profesor are douăzeci și două de foi pentru grup.','There are twenty students in the library. Ana has two books, and Radu has three notebooks. On the large table are twelve apples and four glasses of water. A teacher has twenty-two sheets for the group.',[['foaie','sheet of paper'],['pahar','glass'],['douăzeci','twenty']],
[['Choose “two chairs”.','două scaune','doi scaune','două scauni','Neuter scaun uses feminine agreement in the plural.'],['Choose “twenty books”.','douăzeci de cărți','douăzeci cărți','douăzeci carte','Use de between this cardinal number and the noun.'],['How many glasses of water are on the table?','Four','Twelve','Twenty','Patru pahare cu apă means four glasses of water.']],
'Count five kinds of objects. Ask how many books there are, then answer with a number above twenty.');
L('Place and movement','Use în, la, din, pe, lângă, and cu in context.',
'Prepositions express relationships rather than matching English words one for one. În often means in/into; la means at/to; din means from/out of; pe often means on; lângă means near; cu means with. Compare Sunt în cameră, merg la școală, and vin din oraș. A destination after merg commonly uses la or în depending on the phrase.\n\nIn many unmodified location phrases, Romanian leaves off the definite article: la școală, în parc, pe masă. A modifier or different context can change this: în parcul mare. Acasă means at home or home as a destination; do not add la before it. The paired expression de acasă means from home.',
'Merg de acasă la școală.','I go from home to school.','Ana pleacă de acasă și merge la școală. Școala este lângă parc. În parc sunt copii, iar pe o bancă este un caiet. Radu vine din oraș cu un prieten. Ei merg împreună la bibliotecă.','Ana leaves home and goes to school. The school is near the park. There are children in the park, and on a bench is a notebook. Radu comes from town with a friend. They go to the library together.',[['lângă','near'],['bancă','bench'],['împreună','together']],
[['Choose “at home”.','acasă','la acasă','în acasă','Acasă already functions as a place adverb; it does not need la.'],['Which phrase means “from the city”?','din oraș','pe oraș','cu oraș','Din indicates origin or movement from inside a place.'],['What is on the bench?','A notebook','A book','A glass','Pe o bancă este un caiet.']],
'Describe a route from home to a familiar place. Mention something on, in, and near something else.');
L('Time, dates, and frequency','Say when something happens and how often.',
'Use astăzi/azi for today, ieri for yesterday, and mâine for tomorrow. Parts of the day often function as time adverbs in their definite form: dimineața (in the morning), seara (in the evening). La ora opt means at eight o’clock. Ask Cât este ceasul? or Cât e ceasul? for the time.\n\nExpress frequency with în fiecare zi (every day), de două ori pe săptămână (twice a week), uneori (sometimes), and niciodată (never, with a negative verb). Days take forms such as luni, marți, miercuri; lunea can indicate on Mondays. A date commonly uses întâi for the first day: întâi mai; other dates use cardinal numbers in conventional date expressions.',
'Citesc în fiecare seară.','I read every evening.','Luni, Ana lucrează de la ora nouă până la ora cinci. Seara citește o oră. Marți merge la bibliotecă. Radu citește de două ori pe săptămână, dar Ana citește în fiecare zi. Mâine, ei merg în parc la ora opt.','On Monday, Ana works from nine to five. In the evening she reads for an hour. On Tuesday she goes to the library. Radu reads twice a week, but Ana reads every day. Tomorrow they go to the park at eight.',[['săptămână','week'],['uneori','sometimes'],['oră','hour']],
[['Which expression means “twice a week”?','de două ori pe săptămână','în fiecare zi','la ora două','De două ori counts two occurrences; pe săptămână sets the interval.'],['How do you say “at eight o’clock”?','la ora opt','în opt ora','de opt ore','La ora opt identifies a clock time; opt ore is a duration.'],['Who reads every day?','Ana','Only Radu','Neither person','Ana citește în fiecare zi.']],
'Describe your weekly schedule with two clock times and three frequency expressions.');
L('Reflexive verbs and routines','Place mă, te, se, ne, vă, and se with daily actions.',
'Reflexive verbs use a pronoun agreeing with the subject: mă trezesc, te trezești, se trezește, ne trezim, vă treziți, se trezesc. The pronoun normally comes before the present-tense verb. Some actions literally affect the subject, such as mă spăl; others are simply learned as reflexive verbs, such as mă gândesc.\n\nNegation comes first: Nu mă trezesc devreme. The subject can still be omitted because the pronoun and verb identify it. Distinguish mă uit (I look/watch) from uit (I forget); adding se is not just decoration. Learn reflexive verbs with their pronoun pattern and any required preposition: mă gândesc la tine.',
'Mă trezesc la ora șapte.','I wake up at seven.','În fiecare dimineață mă trezesc la ora șapte. Mă spăl, beau apă și mă pregătesc pentru școală. Ana se trezește mai târziu. Noi ne întâlnim lângă parc și mergem împreună la bibliotecă. Seara, mă uit la un film și mă gândesc la ziua următoare.','Every morning I wake up at seven. I wash, drink water, and get ready for school. Ana wakes up later. We meet near the park and go to the library together. In the evening, I watch a film and think about the next day.',[['a se trezi','to wake up'],['devreme','early'],['a se gândi','to think']],
[['Complete: Noi ___ trezim devreme.','ne','se','mă','Noi takes the reflexive pronoun ne.'],['Choose the negative of “Mă trezesc.”','Nu mă trezesc.','Mă nu trezesc.','Mă trezesc nu.','Nu precedes the reflexive clitic and finite verb.'],['Where do the people meet?','Near the park','Inside the school','At home','Ne întâlnim lângă parc identifies the meeting place.']],
'Describe your morning with three reflexive verbs, then retell it about a friend using se.');
// Chapter 5
L('Possessive adjectives','Agree my, your, our, and their with the thing possessed.',
'A possessive agrees with the possessed noun, not with the owner: prietenul meu, prietena mea, prietenii mei, prietenele mele. The owner is still “I” in all four. With an ordinary definite noun, put the possessive after it. For our, use nostru/noastră/noștri/noastre; for your plural, vostru/voastră/voștri/voastre.\n\nLui (his), ei (her), and lor (their) do not change to match the possessed noun: cartea lui, cărțile lui. Său/sa/săi/sale can refer to his or her, with context resolving the owner. When the noun is absent or the structure requires a linker, use al/a/ai/ale: Cartea este a mea. The linker agrees with what is owned.',
'Cartea aceasta este a mea.','This book is mine.','Ana are un caiet nou. Caietul ei este pe masă. Radu caută cartea lui, dar cartea este în geanta Mariei. Prietenii noștri sunt în gară. Bagajele lor sunt mari, iar camera noastră este mică.','Ana has a new notebook. Her notebook is on the table. Radu is looking for his book, but the book is in Maria’s bag. Our friends are at the station. Their bags are large, and our room is small.',[['geantă','bag'],['bagaj','luggage / bag'],['prietenă','female friend']],
[['Complete: prietenele ___.','mele','meu','mei','Prietenele is feminine plural, so the form is mele.'],['Choose “Her books”.','cărțile ei','cărțile ea','cartea ei','Ei as a genitive possessor is invariant; cărțile is plural.'],['Where is Radu’s book?','In Maria’s bag','At the station','In his room','Cartea este în geanta Mariei.']],
'Identify five possessions with meu/mea/mei/mele. Contrast two items belonging to different friends.');
L('This, that, and which','Use demonstratives before and after a noun.',
'For this/these, use acest, această, acești, aceste before a noun: această carte. After a definite noun, use acesta, aceasta, aceștia, acestea: cartea aceasta. The noun is normally unarticulated in the first pattern and definite in the second. Both can identify the same object.\n\nFor that/those, compare acel băiat with băiatul acela, acea carte with cartea aceea. Demonstratives can stand alone: Aceasta este cartea mea. Care asks which: Care carte? Context helps distinguish the question word care from relative care in later lessons. Learn the close/far and masculine/feminine contrasts as sets.',
'Această carte este interesantă.','This book is interesting.','În librărie sunt multe cărți. Ana alege această carte despre munți. Radu preferă cartea aceea despre orașe. Maria întreabă: „Care caiet este al meu?” Caietul acesta este al ei, iar caietul acela este al Anei.','There are many books in the bookshop. Ana chooses this book about mountains. Radu prefers that book about cities. Maria asks, “Which notebook is mine?” This notebook is hers, while that notebook is Ana’s.',[['acest','this (masculine)'],['librărie','bookshop'],['munte','mountain']],
[['Which phrase has the same meaning as “această carte”?','cartea aceasta','carte aceasta','aceasta cartea','After the noun, the noun takes its definite article and the demonstrative uses the longer form.'],['Choose the feminine plural “these”.','aceste','acești','acest','Aceste agrees with feminine plural nouns.'],['Which subject does Ana’s book concern?','Mountains','Cities','Cooking','Această carte despre munți is a book about mountains.']],
'Point out near and distant objects using both noun positions: această carte and cartea aceasta.');
L('Comparisons and superlatives','Compare places, people, and experiences.',
'Use mai + adjective + decât to make a comparison: mai mare decât. The adjective still agrees: o cameră mai mare, două camere mai mari. For equality, use la fel de + adjective + ca: la fel de mare ca. Mai puțin expresses less; foarte expresses very rather than the most.\n\nThe relative superlative uses cel/cea/cei/cele mai: cel mai frumos oraș, cea mai frumoasă stradă, cele mai frumoase case. This demonstrative article agrees with the noun. Do not stack English-style endings onto Romanian adjectives. Mai bine and mai rău commonly compare how well or badly something happens.',
'Brașovul este mai mic decât Bucureștiul.','Brașov is smaller than Bucharest.','Ana preferă camera de sus, pentru că este mai luminoasă decât camera de jos. Radu spune că ambele sunt la fel de liniștite. Maria caută cea mai ieftină cameră. Pentru ei, un loc simplu lângă centru este mai bun decât un hotel mare și scump.','Ana prefers the upstairs room because it is brighter than the downstairs room. Radu says both are equally quiet. Maria is looking for the cheapest room. For them, a simple place near the center is better than a large, expensive hotel.',[['ieftin','cheap'],['scump','expensive'],['luminos','bright']],
[['Complete: cea mai ___ cameră.','ieftină','ieftin','ieftini','Cameră is feminine singular; both cea and ieftină agree.'],['Which expression means “as quiet as”?','la fel de liniștit ca','mai liniștit decât','foarte liniștit','La fel de… ca expresses equality.'],['Who looks for the cheapest room?','Maria','Ana','Radu','Maria caută cea mai ieftină cameră.']],
'Compare two cities and two rooms. Name the most useful item in your bag, using the correct superlative agreement.');
L('Direct objects and pe','Use object clitics and mark definite people.',
'A direct object is the person or thing directly affected by an action. Romanian unstressed direct-object pronouns are mă, te, îl/o, ne, vă, îi/le. They normally come before the present verb: O văd, îl cunosc, le citesc. Gender and number refer to the object, not the subject.\n\nDefinite human direct objects commonly use pe and an accompanying clitic: O văd pe Maria; îl văd pe Radu. With an ordinary inanimate noun, do not add pe mechanically: Citesc cartea. The question “whom?” becomes pe cine: Pe cine vezi? Clitic doubling with personal names is a normal part of Romanian, not an unnecessary repeated object.',
'O văd pe Maria.','I see Maria.','În gară, Ana îl vede pe Radu lângă intrare. Maria nu este acolo. Ana o caută și o sună. În cele din urmă, o vede pe Maria la casa de bilete. Prietenii cumpără biletele și le pun într-o geantă mică.','At the station, Ana sees Radu near the entrance. Maria is not there. Ana looks for her and calls her. Finally, she sees Maria at the ticket office. The friends buy the tickets and put them in a small bag.',[['intrare','entrance'],['bilet','ticket'],['a căuta','to look for']],
[['Choose “I see Radu.”','Îl văd pe Radu.','O văd pe Radu.','Văd la Radu.','Radu is a definite male person: îl doubles the pe-marked object.'],['Which clitic replaces feminine plural cărțile?','le','îi','o','Le is feminine plural accusative; îi is masculine plural accusative or third-person dative.'],['Where is Maria?','At the ticket office','At the entrance','On the train','Ana sees her la casa de bilete.']],
'Describe seeing and calling two friends. Then replace two plural objects with îi or le as appropriate.');
L('Indirect objects and the dative','Say to whom something is given, said, or sent.',
'An indirect object often identifies a recipient. Unstressed dative forms are îmi, îți, îi, ne, vă, le: Îți dau o carte, I give you a book. The direct object is the book; the indirect object is its recipient. Îi can mean to him or to her, so context matters.\n\nWith a named recipient, dative marking and doubling work together: Îi dau Mariei o carte; îi dau lui Radu un caiet. Female names like Maria commonly change to Mariei; masculine names often use lui before the name. Îmi place cartea literally patterns as the book is pleasing to me: the verb agrees with cartea, not with the person experiencing it.',
'Îi dau Mariei o carte.','I give Maria a book.','Ana îi dă Mariei harta și îi explică traseul. Radu le arată prietenilor biletele. „Îți place orașul?” o întreabă pe Ana. Ei îi plac străzile liniștite, dar Mariei îi place piața mare, unde găsește o librărie.','Ana gives Maria the map and explains the route to her. Radu shows the friends the tickets. “Do you like the city?” he asks Ana. She likes the quiet streets, but Maria likes the large square, where she finds a bookshop.',[['hartă','map'],['traseu','route'],['a arăta','to show']],
[['Which word is the recipient in “Îi dau Mariei o carte”?','Mariei','carte','dau','Mariei is dative, identifying who receives the direct object o carte.'],['Complete: Îmi ___ cărțile.','plac','place','plăcea','The grammatical subject is plural cărțile, so the present verb is plac.'],['What does Ana give Maria?','The map','The tickets','A notebook','Ana îi dă Mariei harta.']],
'Give or show imaginary objects to three people using îți, îi, and le. Say two things you like with place/plac.');
L('Genitive possession and case forms','Build forms such as fetei, băiatului, and unui prieten.',
'The genitive expresses possession or a similar relationship: cartea fetei, the girl’s book. Definite genitive and dative forms coincide: băiatului, fetei, copiilor. Indefinite forms use unui, unei, unor: unui băiat, unei fete, unor copii. Feminine singular nouns often use a stem resembling the plural in genitive/dative forms: o fată → unei fete.\n\nWhen a possessive relationship is separated from the definite noun, use al/a/ai/ale: o carte a Mariei, un prieten al Anei. The linker agrees with the possessed item: a with carte, al with prieten. A definite noun directly followed by its genitive usually does not need this linker: cartea Mariei. Distinguish ownership from the dative recipient by the role in the sentence.',
'Acesta este caietul Mariei.','This is Maria’s notebook.','La pensiune, Ana deschide geanta Mariei din greșeală. Caietul fetei este lângă harta orașului. Radu îi dă proprietarei pensiunii cheia camerei. Pe masă este o scrisoare a unui prieten, iar lângă ea sunt fotografiile copiilor.','At the guesthouse, Ana opens Maria’s bag by mistake. The girl’s notebook is beside the city map. Radu gives the guesthouse owner the room key. On the table is a letter from a friend, and beside it are the children’s photographs.',[['pensiune','guesthouse'],['cheie','key'],['scrisoare','letter']],
[['Choose “a girl’s book”.','cartea unei fete','cartea unei fată','cartea unui fete','Unei is feminine singular genitive/dative and fată changes to fete.'],['Complete: o carte ___ Mariei.','a','al','ai','The linker agrees with feminine singular carte, hence a.'],['What does Radu give the owner?','The room key','A letter','A city map','Îi dă proprietarei pensiunii cheia camerei.']],
'Describe ownership of four objects. Include a definite owner, an indefinite owner, and one structure with al/a/ai/ale.');
// Chapter 6
L('Perfect compus: completed past','Form the common past with an auxiliary and a participle.',
'The perfect compus normally presents a completed past event. Use am, ai, a, am, ați, au plus a past participle: am citit, ai mers, a lucrat. The auxiliary gives person and number; the participle does not change in this active construction. Am can mean I have in the present or function as a past auxiliary before a participle.\n\nCommon participles include lucrat, citit, mers, făcut, văzut, avut, fost, and luat. Learn irregular participles as vocabulary. Reflexives contract: m-am trezit, te-ai trezit, s-a trezit. Do not add a second present-tense ending to the participle. Time expressions such as ieri and săptămâna trecută help anchor the event.',
'Ieri am mers la gară.','Yesterday I went to the station.','Ieri, Ana a cumpărat bilete pentru toți trei. Radu a făcut o fotografie a gării, iar Maria a citit programul trenurilor. Au plecat dimineața și au ajuns seara. La pensiune, s-au întâlnit cu un prieten și au vorbit despre călătorie.','Yesterday, Ana bought tickets for all three. Radu took a photograph of the station, while Maria read the train timetable. They left in the morning and arrived in the evening. At the guesthouse, they met a friend and talked about the journey.',[['ieri','yesterday'],['a ajunge','to arrive'],['călătorie','journey']],
[['Complete: Voi ___ mers la gară.','ați','au','am','Voi takes the auxiliary ați in the perfect compus.'],['Choose the past participle of a vedea.','văzut','vedem','vede','Văzut is the participle. Vedem and vede are finite present forms.'],['Who read the timetable?','Maria','Ana','Radu','Maria a citit programul trenurilor.']],
'Retell yesterday’s activities in five completed events. Include a făcut, am văzut, and ne-am întâlnit.');
L('The imperfect','Describe past habits, settings, and ongoing actions.',
'The imperfect presents a past activity as ongoing, habitual, or backgrounded rather than as a completed step. Compare mergeam (I was going / used to go) and am mers (I went). Regular imperfect endings are -am, -ai, -a, -am, -ați, -au, attached to the appropriate stem: citeam, citeai, citea, citeam, citeați, citeau.\n\nA fi is irregular: eram, erai, era, eram, erați, erau. A avea gives aveam, aveai, avea, aveam, aveați, aveau. Context distinguishes I and we when their forms coincide. Use the imperfect to set a scene: Era frig, ploua, iar noi așteptam. A completed event can then enter that scene in the perfect compus.',
'Când eram mică, citeam în fiecare seară.','When I was little, I used to read every evening.','Când era copil, Maria mergea des cu trenul. Bunicii ei locuiau într-un sat, iar drumul dura câteva ore. În tren, citea sau privea pe fereastră. Acum călătorește din nou cu prietenii și își amintește cum erau verile de atunci.','When she was a child, Maria often traveled by train. Her grandparents lived in a village, and the trip lasted a few hours. On the train, she read or looked out the window. Now she is traveling again with friends and remembers what those summers were like.',[['copil','child'],['bunici','grandparents'],['sat','village']],
[['Choose “they were”.','erau','erați','eram','Ei/ele takes erau; voi takes erați.'],['Which tense is most suitable for an old repeated habit?','Imperfect','Only future','Only imperative','The imperfect commonly describes repeated past habits without presenting a single completed event.'],['Where did Maria’s grandparents live?','In a village','At a station','In a hotel','Bunicii ei locuiau într-un sat.']],
'Describe a place you knew as a child, including the setting and two repeated habits.');
L('Past events versus background','Combine perfect compus and imperfect in a narrative.',
'Choose a past tense according to how you present the action. The imperfect supplies background or an action in progress; the perfect compus advances the sequence through completed events. Citeam când a sunat telefonul means I was reading when the phone rang. The ringing interrupts or enters the ongoing reading scene.\n\nThe difference is not simply long versus short. Am lucrat trei ore presents a three-hour period as completed; lucram la proiect describes work in progress. Repetition can also be bounded: Am mers acolo de trei ori counts three completed visits. Ask whether you are setting the scene or narrating the next completed step.',
'Citeam când a sunat telefonul.','I was reading when the phone rang.','Ploua, iar trenul mergea încet. Ana citea lângă fereastră, în timp ce Radu dormea. Deodată, telefonul Mariei a sunat. Un prieten le-a spus că îi aștepta în gară. Când au coborât, ploaia s-a oprit și prietenul le-a făcut semn de la intrare.','It was raining, and the train was moving slowly. Ana was reading by the window while Radu slept. Suddenly Maria’s phone rang. A friend told them he was waiting at the station. When they got off, the rain stopped and the friend waved to them from the entrance.',[['ploaie','rain'],['încet','slowly'],['deodată','suddenly']],
[['Choose the background in “Citeam când a sunat telefonul.”','citeam','a sunat','telefonul','Citeam is the ongoing background; a sunat presents the completed event.'],['Can a three-hour action use perfect compus?','Yes, when presented as a completed period.','No, duration always requires imperfect.','Only if it happened today.','Tense choice reflects viewpoint, not a fixed length-of-time threshold.'],['What happened when they got off?','The rain stopped.','The train left early.','Radu bought a book.','Când au coborât, ploaia s-a oprit.']],
'Set a scene with three imperfect verbs, then add two completed events that change the scene.');
L('The pluperfect','Show that one past event happened before another.',
'The pluperfect places an event before another past reference point: Când am ajuns, trenul plecase. The leaving happened earlier than the arriving. Common forms include fusesem (I had been), avusesem (I had had), mersesem (I had gone), and citisem (I had read). It is a single-word tense, not an auxiliary plus participle.\n\nLearn the plural endings carefully: citiserăm, citiserăți, citiseră; merseserăm, merseserăți, merseseră. These forms are common in written storytelling, though conversational speakers may also use other past constructions with clear time markers. Use deja to emphasize already, and până atunci for up to that point.',
'Când am ajuns, trenul plecase.','When I arrived, the train had left.','Ana și Radu au ajuns la peron prea târziu. Trenul plecase deja, iar Maria îi așteptase lângă casa de bilete. Radu uitase ora plecării. Din fericire, Ana cumpărase bilete flexibile. Au schimbat rezervarea și au găsit o cafenea despre care Maria citise înainte de călătorie.','Ana and Radu reached the platform too late. The train had already left, and Maria had waited for them near the ticket office. Radu had forgotten the departure time. Fortunately, Ana had bought flexible tickets. They changed the reservation and found a café Maria had read about before the trip.',[['peron','platform'],['deja','already'],['rezervare','reservation']],
[['Which event happened first in “Când am ajuns, trenul plecase”?','The train left.','I arrived.','They necessarily happened together.','The pluperfect plecase places the departure before the past arrival.'],['Choose “we had read”.','citiserăm','citisem','citiserați','Noi takes citiserăm. Citisem is first-person singular.'],['Why could they change the reservation?','Ana had bought flexible tickets.','The train was free.','Maria owned the café.','Ana cumpărase bilete flexibile explains the possibility.']],
'Describe a missed appointment. Explain what had already happened before you arrived, using two pluperfect forms.');
L('Future plans','Compare voi + infinitive with o să + subjunctive.',
'The standard future uses voi, vei, va, vom, veți, vor plus the bare infinitive: voi merge, vei citi, va lucra. The infinitive does not change with the subject; the auxiliary does. Do not include the dictionary marker a after the auxiliary.\n\nEveryday speech also uses o să plus a subjunctive form: o să merg, o să mergi, o să meargă. The o stays unchanged while the verb carries person. Am să, ai să, are să and related forms offer another future pattern. For present plans with a time expression, the present tense can also be natural: Mâine plec. The next lesson explains să forms directly.',
'Mâine vom merge la muzeu.','Tomorrow we will go to the museum.','Mâine, prietenii vor pleca devreme. Vor vizita un muzeu, apoi o să meargă pe jos prin centru. Ana va lua harta, iar Radu o să cumpere apă. Maria spune că seara vor avea timp pentru o plimbare. Dacă plouă, vor rămâne mai mult în muzeu.','Tomorrow, the friends will leave early. They will visit a museum, then walk through the center. Ana will take the map, and Radu will buy water. Maria says they will have time for a walk in the evening. If it rains, they will stay longer in the museum.',[['mâine','tomorrow'],['muzeu','museum'],['plimbare','walk']],
[['Complete: Noi ___ citi.','vom','voi','vor','Noi uses vom with the bare infinitive citi.'],['Choose a grammatical everyday future.','O să mergem.','O să merge noi.','O să a merge.','O stays fixed; mergem is the first-person plural să form.'],['What will they do if it rains?','Stay longer in the museum','Cancel the whole trip','Go to the station','Vor rămâne mai mult în muzeu gives the alternative plan.']],
'Plan a day using three standard future forms and three o să forms. Include a backup plan.');
L('The subjunctive with să','Express wishes, needs, and possibilities.',
'The present subjunctive begins with să. It often follows desire, necessity, or an intended action: Vreau să citesc; trebuie să plecăm. For most verbs, first- and second-person forms resemble the indicative, while third-person forms change: merge → să meargă, citește → să citească, lucrează → să lucreze. Third-person singular and plural share the same form.\n\nA fi is irregular: să fiu, să fii, să fie, să fim, să fiți, să fie. A avea gives să am, să ai, să aibă, să avem, să aveți, să aibă. A subjunctive clause can have a different subject: Vreau ca Maria să vină. Negation goes after să and before the verb or clitic: să nu pleci.',
'Vreau să citesc în română.','I want to read in Romanian.','Ana vrea să viziteze muzeul, dar Radu trebuie să găsească un bancomat. Maria propune să se întâlnească toți în piață la prânz. Este important să aibă apă și să nu plece prea târziu. Ana speră ca prietenii ei să fie gata la timp.','Ana wants to visit the museum, but Radu needs to find an ATM. Maria suggests that they all meet in the square at noon. It is important that they have water and not leave too late. Ana hopes her friends will be ready on time.',[['a trebui','to need to / must'],['gata','ready'],['prânz','noon / lunch']],
[['Complete: Vreau ca ea să ___.','vină','vine','veni','The third-person present subjunctive of a veni is să vină.'],['Choose “so that you do not leave” in a să clause.','să nu pleci','nu să pleci is always the neutral pattern','să pleci nu','Within the negative subjunctive clause, nu follows să.'],['Where does Maria propose meeting?','In the square','At the ATM','Inside the museum','Maria propune să se întâlnească toți în piață.']],
'Say what you want to do, what you need to do, and what you want a friend to do. Use different subjects in one sentence.');
// Chapter 7
L('Commands and requests','Build affirmative and negative imperatives, including polite requests.',
'The imperative addresses someone directly. Singular forms must often be learned: vino (come), mergi (go), fă (do), ia (take), citește (read). Plural and polite forms generally resemble the second-person plural present: veniți, mergeți, faceți, luați, citiți. Add te rog or vă rog to make a request more courteous.\n\nThe negative singular usually uses nu + the bare infinitive: Nu pleca! Nu face asta! Plural negatives normally use nu + the plural imperative: Nu plecați! Affirmative object clitics follow the imperative with a hyphen: Citește-o! Negative clitics precede the verb: Nu o citi! Reflexives follow the same contrast: Grăbește-te! Nu te grăbi!',
'Citiți textul, vă rog.','Read the text, please.','Ghidul le spune prietenilor: „Luați apă și încălțați-vă bine! Nu plecați fără hartă.” Radu caută telefonul. „Pune-l în geantă”, îi spune Ana. Maria deschide ușa și întreabă: „Mergem?” Ghidul zâmbește: „Așteptați puțin, vă rog. Vreau să vă arăt traseul înainte să pornim.”','The guide tells the friends, “Take water and put on suitable shoes! Do not leave without a map.” Radu looks for his phone. “Put it in the bag,” Ana tells him. Maria opens the door and asks, “Are we going?” The guide smiles: “Wait a little, please. I want to show you the route before we set off.”',[['a aștepta','to wait'],['a porni','to set off'],['puțin','a little']],
[['Choose the negative singular command of a face.','Nu face!','Nu fă!','Nu faciți!','Negative singular generally uses the infinitive face, while affirmative singular is fă.'],['Choose “Read it!” for feminine carte.','Citește-o!','O citește! is the standard neutral imperative form','Citește îi!','In an affirmative command, the unstressed object follows with a hyphen.'],['What does the guide want to show before leaving?','The route','A restaurant','The tickets','Vreau să vă arăt traseul înainte să pornim.']],
'Give a friend three travel instructions. Make one negative, one reflexive, and one polite plural request.');
L('Relative clauses','Use care, pe care, căruia, and căreia to identify a noun.',
'A relative clause adds information about a noun. When care is the subject of its clause, use care: omul care citește, the man who reads. When it is a direct object, use pe care and a doubling object pronoun: cartea pe care o citesc, the book that I read. The pe care pattern applies to things as well as people in this relative construction.\n\nA dative relative uses forms such as căruia, căreia, cărora and often a matching clitic: fata căreia îi scriu. A genitive relative adds an agreeing possessive linker: scriitoarea a cărei carte o citesc. The relative form follows the antecedent’s gender/number and case role; the possessive linker agrees with the possessed noun.',
'Cartea pe care o citesc este nouă.','The book that I am reading is new.','La muzeu, Ana întâlnește o femeie care restaurează cărți. Volumul pe care îl ține în mână este foarte vechi. Radu fotografiază masa la care lucrează restauratoarea, cu permisiunea ei. Maria îi mulțumește femeii căreia i-a pus atâtea întrebări. Este prima persoană din călătorie a cărei poveste vor să o înregistreze.','At the museum, Ana meets a woman who restores books. The volume she holds is very old. Radu photographs the table where the restorer works, with her permission. Maria thanks the woman to whom she has asked so many questions. She is the first person on the journey whose story they want to record.',[['a restaura','to restore'],['volum','volume'],['permisiune','permission']],
[['Choose “the book that I read”.','cartea pe care o citesc','cartea care eu citesc','cartea cine citesc','A direct-object relative normally uses pe care with a doubling clitic.'],['Which relative form is feminine singular dative?','căreia','căruia','care','Căreia is feminine singular; căruia is masculine/neuter singular.'],['What does the woman restore?','Books','Trains','Windows','O femeie care restaurează cărți identifies her work.']],
'Describe a person who does something, an object you use, and a person you write to. Include three different relative patterns.');
L('Pronoun order and contractions','Place object clitics with present, past, future, and commands.',
'Unstressed object pronouns occupy a fixed neighborhood around the verb. In the present, they normally precede it: Îi dau cartea; o văd. In compound past forms, contractions are common: l-am văzut, i-am dat. Feminine singular accusative o follows the participle in the perfect compus: am văzut-o.\n\nWhen combining a dative recipient and an accusative object, use the corresponding cluster: mi-l dă, mi-o dă, ți le dau. Mi-o dă means he/she gives it to me, with a feminine singular object. Affirmative imperative clusters follow the verb: Dă-mi-o! Negatives precede: Nu mi-o da! Learn full clusters in context rather than rearranging the stressed dictionary pronouns.',
'Maria mi-a dat-o ieri.','Maria gave it to me yesterday.','Ana caută scrisoarea. Maria i-a dat-o dimineață, dar Ana a pus-o într-un buzunar și a uitat unde. Radu îi arată geanta: „Poate ai pus-o aici.” Când o găsește, Ana spune: „Nu mi-o mai ascundeți printre hărți!” Maria râde: „Citește-ne-o, atunci. Vrem să auzim ce scrie.”','Ana looks for the letter. Maria gave it to her in the morning, but Ana put it in a pocket and forgot where. Radu points to the bag: “Maybe you put it here.” When she finds it, Ana says, “Do not hide it among my maps anymore!” Maria laughs: “Read it to us, then. We want to hear what it says.”',[['buzunar','pocket'],['a ascunde','to hide'],['a auzi','to hear']],
[['Choose “I saw her” in perfect compus.','Am văzut-o.','O am văzut.','Am o văzut.','Feminine accusative o follows the participle in this construction.'],['Choose the affirmative command “Give it to me” for a feminine object.','Dă-mi-o!','Mi-o dă! as the neutral command','Dă o-mi!','The imperative takes the following dative–accusative cluster mi-o.'],['Where did Ana first put the letter?','In a pocket','On the platform','Under a table','Ana a pus-o într-un buzunar.']],
'Explain giving a map to a friend and receiving a letter. Replace both objects with pronouns, then give a command involving one of them.');
L('Real conditions','Use dacă to connect a plausible condition and its result.',
'Dacă introduces an if-clause. For an open or realistic future possibility, use an indicative condition and an appropriate result: Dacă plouă, rămânem aici. Romanian can use the present for both clauses when the future meaning is clear, or a future result: Dacă plouă, vom rămâne aici.\n\nA real condition is not the same as a question about whether something is true. Compare Dacă vine, plecăm (if he comes, we leave) with Nu știu dacă vine (I do not know whether he is coming). Punctuation and context distinguish the roles. In a condition-first sentence, a comma normally separates the clauses.',
'Dacă plouă, rămânem aici.','If it rains, we stay here.','Prietenii vor să plece pe jos, dar cerul este întunecat. Dacă începe ploaia, vor lua autobuzul. Dacă vremea rămâne bună, vor urma drumul de lângă râu. Maria nu știe dacă ghidul vine cu ei. Ana spune că, dacă el nu poate veni, vor cere o hartă mai detaliată.','The friends want to leave on foot, but the sky is dark. If it starts raining, they will take the bus. If the weather stays good, they will follow the road by the river. Maria does not know whether the guide is coming with them. Ana says that if he cannot come, they will ask for a more detailed map.',[['vreme','weather'],['râu','river'],['cer','sky']],
[['Choose a real condition.','Dacă am timp, vin.','Dacă aș avea timp, aș veni.','Aș fi venit.','Present indicative am frames an open condition; the conditional frames a hypothetical one.'],['What does dacă mean in “Nu știu dacă vine”?','whether','because','although','Here dacă introduces an indirect yes/no question: whether he is coming.'],['What will they do if rain begins?','Take the bus','Wait at the library','Buy more books','Dacă începe ploaia, vor lua autobuzul.']],
'Make a plan with three real conditions: good weather, rain, and a late train.');
L('Hypothetical conditions','Use aș, ai, ar, am, ați, ar with an infinitive.',
'The present conditional uses aș, ai, ar, am, ați, ar plus a bare infinitive: aș merge, ai citi, ar lucra. The auxiliary identifies the subject. Contrast am citit (we/I read, compound past) with am citi (we would read): the second verb’s form matters.\n\nA hypothetical if-sentence commonly uses conditional in both clauses: Dacă aș avea timp, aș veni. It presents an imagined or less certain situation rather than simply predicting an open possibility. Conditional forms also soften requests: Aș dori o cameră; ați putea să mă ajutați? Courtesy does not require an explicit if-clause.',
'Dacă aș avea timp, aș veni.','If I had time, I would come.','Radu privește o fotografie veche a orașului. Dacă ar putea, ar petrece încă o săptămână aici. Ana ar vrea să vorbească mai mult cu restauratoarea, iar Maria ar vizita arhiva. Totuși, au bilete pentru dimineață. „Am putea schimba planul”, spune Radu, „dar atunci am avea mai puțin timp la următoarea oprire.”','Radu looks at an old photograph of the city. If he could, he would spend another week here. Ana would like to talk more with the restorer, while Maria would visit the archive. However, they have tickets for the morning. “We could change the plan,” Radu says, “but then we would have less time at the next stop.”',[['oprire','stop'],['arhivă','archive'],['a petrece','to spend (time)']],
[['Complete: Eu ___ merge.','aș','ar','am','The first-person singular conditional auxiliary is aș.'],['Choose a polite request.','Ați putea să mă ajutați?','Ajutați-mă! is always the most softened form','Eu ajut.','The conditional ați putea softens the request: could you help me?'],['What would Maria visit?','The archive','The coast','The café','Maria ar vizita arhiva.']],
'Describe an imaginary extra day in a city. Make one polite request using ați putea.');
L('Past counterfactuals','Express an unreal past with aș fi + participle.',
'The past conditional combines the conditional auxiliary, fi, and a past participle: aș fi mers, ai fi citit, ar fi venit. Fi does not change. It describes a possible past event that did not necessarily occur, often something that would have happened under different circumstances.\n\nFor a past unreal condition, use Dacă aș fi știut, aș fi venit. Both clauses commonly use the past conditional. Do not replace the participle with a present or infinitive form. A mixed-time condition can connect a past cause with a present consequence: Dacă aș fi dormit, acum nu aș fi obosit. Identify the timeline before selecting the forms.',
'Dacă aș fi știut, aș fi venit.','If I had known, I would have come.','Maria află că în seara trecută a fost un concert lângă pensiune. Dacă ar fi știut, ar fi mers împreună cu Ana și Radu. Radu spune că ar fi auzit muzica dacă nu ar fi închis fereastra. Nu pot schimba seara trecută, dar pot întreba gazda ce se întâmplă mâine. De data aceasta, nu vor să piardă ocazia.','Maria learns that there was a concert near the guesthouse last night. If she had known, she would have gone with Ana and Radu. Radu says he would have heard the music if he had not closed the window. They cannot change last night, but they can ask the host what is happening tomorrow. This time, they do not want to miss the opportunity.',[['ocazie','opportunity'],['gazdă','host'],['concert','concert']],
[['Complete: Aș fi ___ mai devreme.','venit','veni','vin','Past conditional requires a participle: venit.'],['Which sentence describes a past unreal condition?','Dacă aș fi știut, aș fi venit.','Dacă știu, vin.','Mâine voi veni.','Both clauses use past conditional to imagine a different past.'],['Why did they miss the concert?','They did not know about it.','They had no money.','The concert was canceled.','Dacă ar fi știut, ar fi mers implies the missing knowledge.']],
'Retell a travel mistake and imagine two different outcomes with dacă… aș fi….');
// Chapter 8
L('Negative and indefinite pronouns','Use nimeni, nimic, cineva, ceva, and niciun.',
'Romanian normally uses negative concord: Nimeni nu vine, Nu văd nimic. The negative pronoun does not cancel nu. Nimeni refers to no person, nimic to no thing, and niciodată to no time. Their position can change emphasis, while the negative finite verb remains.\n\nIndefinite positive forms include cineva (someone), ceva (something), undeva (somewhere), and cândva (sometime). Niciun/nicio modify a noun: niciun tren, nicio carte. Case inflection also appears: nimănui (to nobody), cuiva (to someone), niciunui prieten. Do not confuse niciun as a determiner with separate nici un in special coordinated or contrastive structures.',
'Nimeni nu este aici.','Nobody is here.','Ana bate la ușa biroului, dar nimeni nu răspunde. Nu este niciun anunț pe perete și nu se aude nimic. Radu vede ceva sub ușă: un plic pe care scrie numele gazdei. Maria propune să întrebe pe cineva de la recepție înainte să atingă plicul. Poate că proprietarul este undeva în apropiere.','Ana knocks on the office door, but nobody answers. There is no notice on the wall and nothing can be heard. Radu sees something under the door: an envelope bearing the host’s name. Maria suggests asking someone at reception before touching the envelope. Perhaps the owner is somewhere nearby.',[['plic','envelope'],['nimeni','nobody'],['ceva','something']],
[['Choose a standard negative sentence.','Nimeni nu vine.','Nimeni vine.','Nimeni da vine.','Romanian negative concord normally requires nu with nimeni.'],['Which form means “to someone”?','cuiva','cineva','nimănui','Cuiva is the genitive/dative form of cineva; nimănui means to nobody.'],['What does Radu see under the door?','An envelope','A ticket','A key','Un plic is the object under the door.']],
'Describe an empty station using nimeni, nimic, and niciun. Then add someone or something unexpected.');
L('Quantifiers and distributives','Choose fiecare, toți, câțiva, mult, and destul.',
'Fiecare is grammatically singular: Fiecare student are o carte. Toți/toate are plural: Toți studenții au cărți. Câțiva and câteva mean a few with masculine and feminine/neuter plural agreement. Unii/unele mean some as pronouns or determiners, depending on context.\n\nMult/multă/mulți/multe agrees when modifying a noun: mult timp, multă apă, mulți oameni, multe case. Destul can be an adverb, but with a noun use an agreeing form plus de: destulă apă, destule cărți; destul de mare means big enough. Distinguish the quantity of an object from the degree of an adjective.',
'Fiecare student are o carte.','Each student has a book.','În barcă sunt câțiva călători și multe bagaje. Fiecare persoană primește o vestă. Toți ascultă explicațiile ghidului, dar unii pun întrebări despre traseu. Ana verifică dacă au destulă apă pentru ziua întreagă. Maria a cumpărat câteva mere, iar Radu spune că mâncarea este suficientă pentru toți.','There are a few travelers and many bags in the boat. Each person receives a life jacket. Everyone listens to the guide’s explanations, but some ask questions about the route. Ana checks whether they have enough water for the whole day. Maria bought a few apples, and Radu says the food is sufficient for everyone.',[['fiecare','each'],['câteva','a few (feminine/neuter)'],['destul','enough']],
[['Complete: Fiecare student ___ o carte.','are','au','avem','Fiecare takes singular agreement even when the group contains many people.'],['Choose “a few books”.','câteva cărți','câțiva cărți','fiecare cărți','Cărți is feminine plural, requiring câteva.'],['What does each person receive?','A life jacket','A map','A notebook','Fiecare persoană primește o vestă.']],
'Describe supplies for a group with fiecare, toți, câteva, and destulă.');
L('Passive voice','Shift attention from the doer to the affected object.',
'The analytical passive uses a form of a fi and an agreeing past participle: Cartea este citită de Ana. Compare active Ana citește cartea. The original object becomes the passive subject, so the participle agrees: cărțile sunt citite; textul este citit; textele sunt citite. An agent can be introduced with de or de către.\n\nChange the tense of a fi to locate the event: a fost construită (was built), va fi construită (will be built). Context distinguishes an event passive from a resulting state: ușa este închisă can mean the door is closed. Romanian often prefers a se construction when the doer is general or irrelevant; that pattern has its own later section.',
'Cartea este citită de Ana.','The book is read by Ana.','La muzeu, ghidul explică felul în care sunt păstrate documentele. Scrisorile sunt curățate de specialiști, apoi sunt fotografiate. O hartă veche a fost restaurată anul trecut. Vizitatorii nu o pot atinge, deoarece hârtia este fragilă. Maria observă că fiecare obiect este însoțit de o explicație despre locul unde a fost găsit.','At the museum, the guide explains how documents are preserved. The letters are cleaned by specialists, then photographed. An old map was restored last year. Visitors cannot touch it because the paper is fragile. Maria notices that each object is accompanied by an explanation of where it was found.',[['document','document'],['fragil','fragile'],['a păstra','to preserve / keep']],
[['Complete: Scrisorile sunt ___.','citite','citit','citită','Scrisorile is feminine plural, requiring citite.'],['How is past time marked in “a fost construită”?','By the past form of a fi','By changing the participle to an infinitive','By removing a fi','A fost is past; construită agrees with a feminine singular subject.'],['Why can visitors not touch the map?','The paper is fragile.','The map is still wet.','The room is closed.','Deoarece hârtia este fragilă gives the reason.']],
'Transform three active sentences about a museum into passive sentences, preserving tense and agreement.');
L('Infinitive, participle, gerund, and supine','Recognize non-finite verb forms and their jobs.',
'Non-finite forms do not carry a complete person-and-tense paradigm. The infinitive is the dictionary form with a: a citi; after some auxiliaries the a is absent: pot citi, voi citi. A participle such as citit builds compound tenses and can act adjectivally, with agreement when needed: carte citită.\n\nThe gerund often ends in -ând or -ind: mergând, citind. It can express an accompanying action: Mergea cântând. Make sure the understood subject is clear; avoid a detached gerund with an unintended subject. The supine often uses de plus a participle-shaped form: o carte de citit, am de lucru. It commonly expresses a task, purpose, or suitability.',
'Am o carte de citit.','I have a book to read.','Așteptând barca, Ana citește notițele din caiet. Are încă două pagini de tradus și câteva întrebări de pus ghidului. Radu vine cântând încet, cu aparatul foto în mână. Maria îi amintește că trebuie să ceară voie înainte de a fotografia oamenii. Nimeni nu vrea să transforme o întâlnire firească într-un spectacol.','While waiting for the boat, Ana reads the notes in her notebook. She still has two pages to translate and a few questions to ask the guide. Radu comes along singing quietly, camera in hand. Maria reminds him that he must ask permission before photographing people. Nobody wants to turn a natural encounter into a spectacle.',[['a traduce','to translate'],['a cere voie','to ask permission'],['întâlnire','meeting / encounter']],
[['Which form is a gerund?','citind','a citi','citit','Citind is the gerund; a citi is infinitive and citit is participle.'],['Which phrase contains a supine?','o carte de citit','o carte citită','citesc o carte','De citit identifies a task or intended use in this noun phrase.'],['What must Radu do before photographing people?','Ask permission','Translate two pages','Buy a new camera','Trebuie să ceară voie înainte de a fotografia oamenii.']],
'Explain what you have to read, write, or finish. Describe one action happening while another takes place, using a gerund.');
L('Linking ideas','Build cause, contrast, concession, and purpose clauses.',
'Connectors tell a reader how ideas relate. Și adds; dar contrasts; sau offers an alternative. Pentru că and deoarece introduce a cause: Rămân pentru că plouă. Deși introduces a concession: Deși plouă, plecăm. The fact in a deși clause does not prevent the main event.\n\nUse ca să or pentru a for purpose: Plec devreme ca să ajung la timp. În timp ce can mark simultaneous actions or a contrast. Totuși means nevertheless and connects a thought to an earlier one without behaving exactly like a subordinating conjunction. Choose a connector for its logical role, not just to make a sentence longer.',
'Deși plouă, plecăm.','Although it is raining, we are leaving.','Deși drumul pe apă este mai lung, prietenii aleg barca pentru că vor să asculte explicațiile ghidului. Ana notează numele locurilor, în timp ce Radu privește malul. Maria lasă telefonul în geantă ca să poată urmări păsările. Nu văd tot ce sperau; totuși, liniștea călătoriei le schimbă ritmul și îi face mai atenți.','Although the water route is longer, the friends choose the boat because they want to listen to the guide. Ana notes place names while Radu watches the bank. Maria leaves her phone in her bag so she can watch the birds. They do not see everything they hoped for; nevertheless, the journey’s quiet changes their pace and makes them more attentive.',[['deși','although'],['totuși','nevertheless'],['mal','bank / shore']],
[['Which connector introduces a concession?','deși','pentru că','și','Deși means although: the subordinate fact does not block the main event.'],['Which phrase expresses purpose?','ca să ajung la timp','pentru că am ajuns','deși am ajuns','Ca să introduces an intended outcome: so that I arrive on time.'],['Why does Maria put her phone away?','To watch the birds','Because it is broken','To buy a ticket','Ca să poată urmări păsările states her purpose.']],
'Tell a short story using one cause, one concession, and one purpose. Explain why each connector fits.');
L('Reported speech','Report statements, questions, and requests.',
'Introduce a reported statement with că: Ana spune că vine. Romanian does not require English-style automatic tense backshift in every context: Ana a spus că vine can be natural. Choose tense according to the actual timeline and viewpoint, while adjusting person and time/place expressions as needed.\n\nFor a reported yes/no question, use dacă: A întrebat dacă venim. Retain a question word in an information question: A întrebat unde stăm. A reported command or request often uses să: Ne-a rugat să așteptăm. Do not preserve the direct speech’s question punctuation inside an ordinary reported declarative sentence.',
'Ana a spus că vine mâine.','Ana said she is coming tomorrow.','Ghidul le-a spus că barca pleacă devreme și i-a rugat să fie la ponton înainte de opt. Maria a întrebat dacă pot lua bagajele mari. El a răspuns că spațiul este limitat și le-a recomandat să aducă doar lucrurile necesare. Radu a întrebat unde pot lăsa restul bagajelor, iar Ana a notat adresa pensiunii.','The guide told them the boat leaves early and asked them to be at the jetty before eight. Maria asked whether they could take large bags. He replied that space is limited and recommended bringing only necessary things. Radu asked where they could leave the rest of the luggage, and Ana wrote down the guesthouse address.',[['ponton','jetty'],['necesar','necessary'],['adresă','address']],
[['Report the yes/no question “Veniți?”','A întrebat dacă venim.','A întrebat că venim.','A întrebat venim?','Dacă introduces an indirect yes/no question.'],['Report the request “Așteptați!”','Ne-a rugat să așteptăm.','Ne-a rugat că așteptăm.','Ne-a rugat dacă așteptăm.','Requests commonly take a să clause.'],['Why should they bring only necessities?','Space is limited.','The journey is canceled.','The boat has no guide.','El a răspuns că spațiul este limitat.']],
'Report a conversation about travel plans. Include a statement, a yes/no question, a where-question, and a request.');
// Chapter 9
L('Subjunctive nuance and past forms','Distinguish time and meaning across să constructions.',
'The subjunctive is a mood, not simply a future tense. Present să forms can refer to an intended, required, desired, or otherwise non-asserted action: Vreau să vină; trebuie să plecăm. The same construction can receive a present or future interpretation from context. A direct wish may stand alone: Să ai o zi bună!\n\nThe perfect subjunctive uses să fi + participle, with the same form for all persons: să fi venit, să fi citit. It places the imagined or evaluated event earlier: E posibil să fi plecat. Context identifies who left. Compare e posibil să plece (may leave / may be leaving) with e posibil să fi plecat (may have left). Do not conjugate fi as fiu in the perfect form.',
'E posibil să fi plecat.','It is possible that they have left.','La Constanța, prietenii caută un librar despre care le vorbise gazda. Magazinul este închis, deși programul de pe ușă spune că ar trebui să fie deschis. E posibil ca librarul să fi plecat la un eveniment. Ana lasă un mesaj și speră să primească un răspuns înainte să se întoarcă la București. Radu propune să nu aștepte lângă ușă: poate că întâlnirea va avea loc mai târziu.','In Constanța, the friends look for a bookseller their host had mentioned. The shop is closed, although its posted hours suggest it should be open. The bookseller may have left for an event. Ana leaves a message and hopes to receive a reply before returning to Bucharest. Radu suggests not waiting by the door: perhaps the meeting will happen later.',[['librar','bookseller'],['răspuns','reply'],['eveniment','event']],
[['Which form means “may have left” after e posibil?','să fi plecat','să plece','să fiu plecat is the person-neutral perfect form','Să fi + participle marks the perfect subjunctive and does not change by person.'],['What does the subjunctive itself always mean?','It has no single fixed time meaning.','Only future time','Only past time','Mood and tense are different. Context locates many present subjunctive forms.'],['Why might the bookseller be absent?','He may have gone to an event.','He has retired, according to the text.','The shop has permanently closed.','E posibil… să fi plecat la un eveniment is a possibility, not a confirmed fact.']],
'Offer three explanations for an unanswered message using e posibil să fi…. Distinguish each inference from something you know.');
L('Impersonal and se constructions','Express general actions, possibility, and reported information.',
'Romanian often uses se when an action is general or its agent is omitted: Aici se vorbește românește. Se poate intra? asks whether entry is possible or allowed. In reflexive-passive constructions the verb agrees with its grammatical subject: Se vinde o carte; se vând cărți. Not every se sentence is literally a person acting on themself.\n\nOther patterns are impersonal: Se spune că… (it is said that), se pare că… (it seems that). A dative experiencer can make the perspective personal: Mi se pare că… means it seems to me that…. Compare an assertion with a cautious report. Se spune does not establish that the reported claim is true; name a source when accuracy matters.',
'Aici se vorbește românește.','Romanian is spoken here.','În librărie se organizează o întâlnire cu cititorii. Pe ușă scrie că se pot pune întrebări după prezentare. Maria observă că se vând și ediții vechi, dar nu se fotografiază paginile fragile. „Mi se pare că librarul este cel de lângă fereastră”, spune Ana. Radu preferă să întrebe înainte să presupună că l-au recunoscut.','A reader meeting is being organized in the bookshop. The notice says questions may be asked after the presentation. Maria notices that old editions are also sold, but fragile pages are not photographed. “It seems to me the bookseller is the person by the window,” Ana says. Radu prefers to ask before assuming they have recognized him.',[['cititor','reader'],['ediție','edition'],['a presupune','to assume']],
[['Complete: Se ___ cărți.','vând','vinde','vândă','In this reflexive-passive construction, plural cărți takes plural vând.'],['Which phrase marks a personal impression?','mi se pare că','este sigur că','am demonstrat că','Mi se pare means it seems to me, making the perspective explicit.'],['When may people ask questions?','After the presentation','Only before opening','Never','Se pot pune întrebări după prezentare.']],
'Describe three rules for a library or museum with se constructions. Add a personal impression with mi se pare.');
L('Literary past: perfect simplu','Recognize narrative forms without confusing them with present tense.',
'The perfect simplu is a completed past tense found in literary narration and regional speech, especially in parts of southwestern Romania. Common literary forms include zise (said), făcu (did), merse (went), and văzu (saw). Its appearance is a register or regional cue, not proof that an event happened a particular number of minutes ago.\n\nThe tense inflects for person: mersei, merseși, merse, merserăm, merserăți, merseră. A fi has fui, fuși, fu, furăm, furăți, fură. For reading, first recognize the third-person forms that move a narrative forward. Compare zise with the conversational a spus and the background spunea. Keep a character’s action distinct from the narrator’s scene-setting.',
'Radu deschise cartea și citi.','Radu opened the book and read.','Librarul scoase un volum subțire de pe raft și îl puse pe masă. „Acesta este pentru voi”, zise el. Ana deschise cartea, iar Radu privi dedicația. Maria nu spuse nimic la început; urmărea felul în care literele vechi se adunau pe pagină. Apoi ridică ochii și întrebă cine scrisese notele de pe margine. Librarul zâmbi: povestea volumului era mai lungă decât credeau.','The bookseller took a slim volume from the shelf and put it on the table. “This is for you,” he said. Ana opened the book, and Radu looked at the dedication. Maria said nothing at first; she was following the way the old letters gathered on the page. Then she looked up and asked who had written the marginal notes. The bookseller smiled: the volume’s story was longer than they thought.',[['raft','shelf'],['dedicație','dedication'],['margine','margin / edge']],
[['Which form is literary completed past?','zise','spunea','spune','Zise is perfect simplu; spunea is imperfect and spune is present.'],['Choose the third-person singular of a merge in perfect simplu.','merse','mersei','merseră','Merse is third-person singular; mersei is first-person singular; merseră is plural.'],['What does Maria ask about?','Who wrote the marginal notes','Where to buy tickets','Whether the train is late','Întrebă cine scrisese notele de pe margine.']],
'Retell a three-event scene with conversational past, then replace the third-person verbs with literary forms from the table.');
L('Vocative, politeness, and register','Address people appropriately and choose a consistent register.',
'The vocative directly addresses someone: Ana!, domnule!, doamnă!, prietene! It is normally separated by a comma: Domnule, mă puteți ajuta? Some forms differ from the nominative, while personal names often remain unchanged. These are patterns to learn with the word rather than endings to add indiscriminately.\n\nDumneavoastră and second-person plural verbs make a polite form of address. Courtesy also uses conditional requests: Ați putea…? In a formal message, use a greeting, explain the request clearly, and close appropriately. Do not switch casually between tu and dumneavoastră for the same addressee. Familiar vocatives can sound warm or rude depending on relationship and tone.',
'Domnule, mă puteți ajuta?','Sir, can you help me?','Ana îi scrie librarului: „Stimate domnule, vă mulțumim pentru timpul acordat. Ne-ați putea spune cine a făcut însemnările din volum? Am dori să cităm povestea corect și să nu atribuim nimănui cuvinte pe care nu le-a spus. Cu stimă, Ana.” Radu citește mesajul și observă cât de diferit sună față de o întrebare trimisă unui prieten.','Ana writes to the bookseller: “Dear Sir, thank you for your time. Could you tell us who made the annotations in the volume? We would like to cite the story correctly and not attribute words to anyone who did not say them. Yours sincerely, Ana.” Radu reads the message and notices how different it sounds from a question sent to a friend.',[['cu stimă','yours sincerely'],['însemnare','annotation / note'],['a cita','to quote / cite']],
[['Which form directly addresses a man politely?','domnule','domnul as the vocative form in this example','domnului','Domnule is the conventional vocative form here.'],['Which is consistent polite address?','Dumneavoastră puteți…','Dumneavoastră poți…','Tu puteți…','Dumneavoastră takes second-person plural puteți.'],['Why does Ana ask about the notes?','To report the story accurately','To sell the book','To shorten the trip','Am dori să cităm povestea corect states the purpose.']],
'Ask a friend for help, then make the same request to an unfamiliar bookseller. Write a short formal follow-up.');
L('Emphasis, discourse, and ambiguity','Track pronouns and organize information across a paragraph.',
'Romanian can move sentence elements to organize given and new information. Cartea aceasta o citesc eu places the book first and emphasizes eu at the end. Object clitics still follow Romanian grammar; fronting is not a license to omit them. Contrast-focused order often needs a clear conversational reason.\n\nIn extended text, pronouns must have recoverable referents. Because subjects are often omitted and îi/lui can be ambiguous, repeat a name when needed. Linking phrases such as în schimb (in contrast), de aceea (therefore), and pe de altă parte (on the other hand) guide the reader. Separate evidence from interpretation with expressions such as potrivit scrisorii and probabil.',
'Cartea aceasta o citesc eu.','I am the one reading this book.','Pe drumul de întoarcere, Ana recitește mesajul librarului. Potrivit lui, însemnările aparțin unei cititoare care călătorise prin aceleași orașe. Radu crede că traseul lor seamănă cu al ei; Maria, în schimb, observă că unele locuri lipsesc. De aceea, cei trei hotărăsc să nu prezinte asemănarea drept o descoperire sigură. Vor păstra în caiet atât informațiile confirmate, cât și întrebările rămase deschise.','On the return journey, Ana rereads the bookseller’s message. According to him, the annotations belong to a reader who had traveled through the same cities. Radu thinks their route resembles hers; Maria, in contrast, notices that some places are missing. Therefore, the three decide not to present the resemblance as a confirmed discovery. They will keep both verified information and open questions in the notebook.',[['în schimb','in contrast'],['potrivit','according to'],['descoperire','discovery']],
[['What does în schimb signal here?','A contrast','A time of day','A direct command','În schimb contrasts Maria’s observation with Radu’s interpretation.'],['How can you reduce ambiguity in a long paragraph?','Repeat a name when the pronoun’s referent is unclear.','Always omit every subject.','Use îi for every person regardless of role.','A repeated name can clarify which person a pronoun would otherwise refer to.'],['Do the friends call the resemblance a confirmed discovery?','No','Yes','Only Ana does.','Ei hotărăsc să nu prezinte asemănarea drept o descoperire sigură.']],
'Summarize a disagreement between two friends. Use explicit names to clarify referents and separate facts from guesses.');
L('Reading literature closely','Combine grammatical analysis with interpretation of an original poem.',
'Literary language can compress a scene through word order, diminutives, figurative description, and omitted information. Start with the literal grammar before interpreting mood. In Somnoroase păsărele, somnoroase is feminine plural and agrees with păsărele. The noun is a diminutive related to pasăre, giving a small or affectionate quality rather than just a different dictionary species.\n\nIn se adună and se ascund, the verbs refer to the birds gathering and hiding. Pe la suggests movement or distribution around the nests; it is not simply identical to pe in pe masă. Read the stanza aloud, observe the contrast between the scene and the final farewell, and distinguish your interpretation from what the lines explicitly state. The Reading room links to the full public-domain text.',
'Păsările se adună lângă cuiburi.','The birds gather near the nests.','Înapoi în București, Maria deschide volumul la o poezie de Mihai Eminescu. Citește încet prima strofă: „Somnoroase păsărele / Pe la cuiburi se adună, / Se ascund în rămurele — / Noapte bună!” Ana recunoaște acordul adjectivului și verbele cu se. Radu își amintește liniștea din Deltă, dar observă că amintirea lui nu este o explicație a poemului. Cei trei închid caietul călătoriei. Acum pot urmări mai mult decât traseul de pe hartă: pot discuta ce spune un text, cum o spune și ce rămâne deschis interpretării.','Back in Bucharest, Maria opens the volume to a poem by Mihai Eminescu. She slowly reads its opening stanza: “Sleepy little birds gather around their nests, hide among the branches—good night!” Ana recognizes the adjective agreement and the verbs with se. Radu remembers the quiet of the Delta, but notices that his memory is not an explanation of the poem. The three close the journey notebook. Now they can follow more than a route on a map: they can discuss what a text says, how it says it, and what remains open to interpretation.',[['cuib','nest'],['rămurea','little branch'],['somnoros','sleepy']],
[['Why is somnoroase feminine plural?','It agrees with păsărele.','It agrees with the author.','All literary adjectives end in -oase.','Somnoroase modifies the feminine plural noun păsărele.'],['What is păsărele?','A diminutive plural related to pasăre','An imperative verb','A past-tense auxiliary','The diminutive adds an affectionate or small-scale quality to the noun.'],['What distinction does Radu make?','His memory is not the same as an explanation of the poem.','The poem is definitely about his trip.','Grammar has no role in reading.','The passage explicitly separates his personal association from textual explanation.']],
'Read the stanza, paraphrase its literal scene, and give one interpretation supported by a word or grammatical feature.');

export const lessons:Lesson[]=raw.map((l,i)=>{
const early=earlyStory[i];
if(early){l.reading=early[0];l.english=early[1];const opts=early.slice(3);const offset=i%3;l.questions[2]={prompt:early[2],options:[...opts.slice(offset),...opts.slice(0,offset)],answer:(3-offset)%3,explanation:'The episode states: '+early[3]+'. Re-read the relevant sentence and compare it with the translation.'};}
else if(storyBridges[i+1]) { const [ro,en]=storyBridges[i+1]; l.reading=ro+'\n\n'+l.reading; l.english=en+'\n\n'+l.english; }
return {...l,id:`ro-${i+1}`,slug:`${String(i+1).padStart(2,'0')}-${l.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`,unit:Math.floor(i/6),tables:lessonTables[i+1]||[]};});
export const grammar=lessons.map(l=>({category:units[l.unit].title,title:l.title,text:l.rule,example:l.example,translation:l.translation,slug:l.slug,tables:l.tables}));
export const languageThemes={ro:{name:'Romanian',primary:'#173d8f',secondary:'#e9b92f',highlight:'#ae2934'},it:{name:'Italian',primary:'#176442',secondary:'#ce2b37',highlight:'#176442'},de:{name:'German',primary:'#252321',secondary:'#e9b92f',highlight:'#a92b32'}};
